{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt minimumskravet (journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik, der beskriver den varige funktionsnedsættelse) og at epikrise/afslutningsbrev som udgangspunkt indgår ved afsluttet behandling. Afvisningsfølgen er korrekt gengivet efter vejledningen. Ingen af rubrikkens material_errors begås, f.eks. gøres epikrise ikke til et absolut krav, og afvisningen forveksles ikke med et materielt afslag."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med: journalmateriale fra de nævnte behandlertyper, beskrivelse af den varige funktionsnedsættelse og epikrise/afslutningsbrev som udgangspunkt ved afsluttet behandling."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer direkte, hvilken lægelig dokumentation der kræves, og hvad der gælder ved afsluttet behandling. Afvisningssætningen er kort og relevant."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse eller vejledning. Der er ingen henvisning til SU-bekendtgørelsen § 37 eller vejledningen."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet i svaret, så kildens gyldighed kan ikke bedømmes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet i svaret, så det kan ikke bedømmes, om kilden understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle væsentlige udsagn har støtte i vejledningens afsnit 4.1 og § 37, stk. 3. Svaret tilføjer ingen uunderbyggede regler, betingelser eller retsvirkninger."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "'Som udgangspunkt' er bevaret ved epikrise/afslutningsbrev, og 'som minimum' er bevaret ved journalkravet. Rubrikkens krav om, at dokumentets titel ikke afgør tilstrækkeligheden, nævnes ikke eksplicit. Det er dog primært et supporting element, og svaret påstår ikke det modsatte."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende: minimumskrav, tillæg ved afsluttet behandling og følgen af manglende dokumentation. Konklusionen følger af de anførte trin."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Skal som minimum' for journaler og 'som udgangspunkt' for epikrise/afslutningsbrev svarer til kilden. Epikrise gøres ikke til et absolut krav. 'Afviser' svarer til vejledningens formulering."}
  },
  "xhaile_coverage": {
    "A30": {"label": "yes", "reason": "Svaret angiver, at dokumentationen som udgangspunkt også indeholder epikrise eller afslutningsbrev, når behandlingsforløbet er afsluttet."},
    "A32": {"label": "yes", "reason": "Svaret dækker punktet om, at dokumentationen indeholder epikrise eller afslutningsbrev, med korrekt forbehold 'som udgangspunkt'."}
  },
  "overall_notes": "Indholdsmæssigt korrekt og fuldstændigt svar uden juridiske fejl og med bevarede forbehold. Svaret nævner dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable efter kildereglen."
}

